// Proactive Business English A1 · Syria Edition · Book 1 · Unit 6 — Answer Key (separate book)
const L = require('./lib');
const { p, h1, h2, h3, pb, sp, stage, box, dlg, table, C } = L;
const out = [];
const sample = (title, paras) => box(title, paras, 'FFFFFF', C.navy);
const note = t => p(`_${t}_`, { color: '595959' });

out.push(h1('Answer Key · Unit 6  The Telephone You Cannot Answer'));
out.push(p('_Proactive Business English · A1 · Book 1 · Syria Edition_', { color: '7F7F7F' }));
out.push(box('Before you teach this unit', [
  'Every task has an answer. Where a task is open, this key gives a **full sample answer** — speaking, reports, checklists and homework too. Learners\' own answers will be different and that is correct.',
  '⚠ **The telephone is the hardest English there is and the class already knows it.** **No face, no paper, no pointing, and the caller does not know you are learning.** **Say that out loud before you start** — **the fear in the room is reasonable and pretending otherwise loses you the quiet learners for the whole unit.**',
  '⚠ **So this unit gives SIX FIXED SENTENCES and nothing else.** **Six, said the same way every time.** **A man with six sentences can answer any telephone in Syria; a man with a hundred words and no sentences cannot answer one.** ⚠ **Do not enrich them. Do not offer alternatives. The fixedness is the method.**',
  '⚠ **Every speaking stage in this unit is done BACK TO BACK.** **Not facing each other.** **A pair who can see each other\'s faces and hands are not practising a telephone call** — **and the whole difficulty of the unit lives in not being able to see.**',
  '⚠ **6.7 closes Book 1 and it is the fifth time in six units that something has gone wrong with nobody at fault.** **Lay the five side by side with the class:** **Abu Raed\'s gate book, Hani\'s eleven swaps, the roll behind the door, Fouad\'s shelf map, a slip under a pad.** **That pattern is what Book 1 has really been teaching.**',
  '**Word counts.** Stage 6 asks for **15 words or more**, stage 7 for **20 to 35**. ⚠ **Cycle 7\'s written task is four sentences in about 30 words**, which is the shape of an A2 Key Writing Part 6 one step down.',
], C.grey, C.navy));

// ===================== 6.1 =====================
out.push(h2('6.1  Sham Trading, good morning'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **Expect _hello_ or _na\'am_ or _aiwa_, and expect at least one learner to say that they let it ring.** **Take that answer seriously; it is the commonest answer in a real workplace class and it is what the unit is for.**'));
out.push(p('**b**  Open. ⚠ **This is the whole cycle hidden in a warm-up.** **Half the room will find that their partner wrote the company name wrong, and the company name is the one word they say forty times a day.** **Let the class discover that before the box tells them.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B — the company name.   **b**  **1** The company, _good morning_, and then silence.  **2** Because _Sham Trading_ is two words the caller has never heard, even though Ammar will say them forty times a day.'));
out.push(p('⚠ **The marked exchange is the last one:** _Then stop and listen. — Then stop and listen. That is the hard part._ **It really is the hard part.** **A learner in a foreign language fills silence because silence feels like failure** — **and on a telephone the silence is where the caller tells you what he wants.**'));
out.push(p('⚠ **And Nour\'s line about _Sorry? Again, please_:** _The same words as Unit one. They still work._ **Point back at 1.6, the cycle teachers skip.** **Five units later it is still the most used thing in the book.**'));
out.push(stage('3', 'Practise – sample with card 1'));
out.push(dlg(null, [
  ['A', '_(ring ring)_'],
  ['B', 'Sham Trading, good morning.'],
  ['A', 'Is that Sham Trading?'],
  ['B', 'Yes. Sham Trading, good morning.'],
  ['A', 'Sorry, I did not hear the name.'],
  ['B', 'Sham… Trading. Good morning. _(slowly)_'],
]));
out.push(note("Back to back, and enforce it. The caller's line Sorry, I did not hear the name is in the card on purpose: it makes the speaker say the company name a second time, slowly, having just been told it was inaudible. That is the correction the cycle needs and it arrives from the partner rather than from the teacher."));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task.** **The company name.** ⚠ **And the instruction that matters: if you could not hear it, that IS the answer.** **Say so.** **A class that reports _I did not get it_ three times out of four has produced the finding the cycle exists for, and nobody has been criticised.**'));
out.push(stage('4', 'Your turn – sample notes'));
out.push(sample('Sample — answering my own telephone', [
  '**Time of day:** 8.00  **What I say:** _Barada Stores, good morning._  **My partner heard:** _Barada Stores_ ✓',
  '**Time of day:** 11.30  **What I say:** _Barada Stores, good morning._  **My partner heard:** _Baradastores_ — one word',
  '**Time of day:** 1.00  **What I say:** _Barada Stores, good afternoon._  **My partner heard:** _Barada Stores_ ✓',
  '**Time of day:** 4.00  **What I say:** _Barada Stores, good afternoon._  **My partner heard:** _"something" Stores_',
]));
out.push(note("The third column is the assessment and the second sample row is the one to point at: Baradastores run together as one word is what a caller hears when a company name is said at speaking speed. The gap between the two words is not decoration. Make them put it in and run the row again."));
out.push(stage('4R', 'Report – sample'));
out.push(p('**Report (sample):**  _Barada Stores, good morning. After twelve o\'clock I say good afternoon._'));
out.push(p('⚠ **Make each learner say it ONCE, slowly, to the whole room.** **Once.** **A second attempt is a different skill** — **the real telephone gives you one.**'));
out.push(p('**Then the count:** how many company names could the class not hear? ⚠ **Put the figure on the board.** **It is usually a third of the room and it is the most persuasive number in the unit.**'));
out.push(p('**Board clinic:** four company names said fast. ⚠ **Nobody gets them all, and that is the lesson** — **do not rescue the class by slowing down until after they have failed.**'));
out.push(stage('5', 'Read'));
out.push(p('**1** _Good afternoon._  **2** Stop and listen.  **3** Five.'));
out.push(p('⚠ **Question 2 is the one worth a minute.** **The second line of the card is an instruction to be SILENT, which is the only such instruction in Book 1** — **and a learner who has read it is more likely to do it.**'));
out.push(stage('6', 'Write with help – sample'));
out.push(sample('Sample answer (28 words)', [
  '**THE COUNTER TELEPHONE — SAY THIS**',
  '**1** _Barada Stores, good morning._  ⚠ **SLOWLY. A gap between the two words. After 12.00: good afternoon.**',
  '**2** Then **stop and listen**.',
  '**3** Not sure? _Sorry? Again, please._',
  '**4** Need a name? _Your name, please._',
  '**5** Need to write? _One moment, please._',
  '⚠ **These five lines answer every call. Do not invent a sixth.**',
]));
out.push(p('**What to credit.** ⚠ **Every line must be WORDS YOU SAY, not an idea.** **_Say the company name_ is an idea; _Barada Stores, good morning_ is a line a man can read off a wall at eight in the morning with a lorry outside.** ⚠ **And the warning sits next to line 1, where the reader will be looking** — **not at the bottom.**'));
out.push(stage('6P', 'Check together – sample'));
out.push(sample('Sample — what a learner actually says', [
  '**(pointing)** Here. **(reading)** "Be polite". ⚠ **That is an idea. What do I SAY?**',
  '**(pointing)** at the bottom. **(reading)** nothing about this. ⚠ **What if I did not understand him?**',
]));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **Two learners read their line 1 out loud and the class answers one question: could you hear the company name?** **It is a test of delivery, not of writing**, **and it is the only place in the unit where the two meet.**'));
out.push(stage('7', 'Write freely – sample (31 words)'));
out.push(sample('Sample answer', [
  '**At the shop the telephone is by the till and whoever is nearest answers it. Everybody says hello and nothing else. Callers ask twice if it is the right shop.**',
]));
out.push(p('⚠ **_Callers ask twice if it is the right shop_ is the finding and plenty of learners will produce it without being prompted.** **That double-check costs a caller four seconds every time and it is caused by one missing sentence.**'));
out.push(stage('7P', 'Respond – sample'));
out.push(p('**Sample slip:**  _Who does not want to answer it?_ — **_The two new girls. They give it to me._**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Three papers, then the count: how many people are afraid of the telephone at work?** **Take the figure without comment and move on.** ⚠ **Do not reassure them.** **The reassurance in this unit is six sentences, and they are about to get them.**'));
out.push(stage('HW', 'Homework – sample'));
out.push(sample('Sample answer (24 words)', [
  '**1 Barada Stores, good morning. SLOWLY. 2 Stop and listen. 3 Sorry? Again, please. 4 Your name, please. 5 One moment, please. Five lines. No sixth.**',
]));

out.push(pb());
// ===================== 6.2 =====================
out.push(h2('6.2  Your name, please'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **This is Unit 1.2 coming back and it should be said so.** **The letters and the count were learned in the first week; here they are done without a face to read.** **Expect a drop in accuracy and tell the class to expect it too** — **the skill has not gone, the conditions have changed.**'));
out.push(p('**b**  ***Your name, please*** **is better.** ⚠ **Ask why _Who are you?_ is wrong.** **It is grammatical and it is not rude in Arabic** — **it is a question you ask a stranger standing in your house, and an office does not ask it.** **Three words instead.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  C — yes, after three tries.   **b**  **1** Spell it.  **2** He reads the letters back, says the number of letters, and says the name.'));
out.push(p('⚠ **Three tries is the content.** _Your name, please_ → _Sorry? Again, please_ → _Can you spell it, please?_ **Nobody in the dialogue is embarrassed by the third attempt and the caller is not annoyed.** **That is the thing to show the class** — **asking three times is normal telephone behaviour, not a confession.**'));
out.push(p('⚠ **And the read-back has THREE parts:** **the letters, the count, the name.** _M, O, U, A, L, L, E, M. Eight letters. Mouallem._ **The count is the check** — **it is Unit 1.2 and Unit 2 doing the same job, and it catches a dropped letter that reading alone does not.**'));
out.push(stage('3', 'Practise – sample with card 1'));
out.push(dlg(null, [
  ['A', '_(ring ring)_'],
  ['B', 'Sham Trading, good morning.'],
  ['A', 'Is Mr Khalil there?'],
  ['B', 'Your name, please.'],
  ['A', 'Mouallem.'],
  ['B', 'Can you spell it, please?'],
]));
out.push(note("Both cards use a real Syrian surname that is hard to hear — Mouallem, Tarabishi — and that is the point. A card with Ali on it teaches nothing. If your class has harder names in it than the cards do, use theirs: a learner spelling their own surname down a telephone is doing the most useful thing in the unit."));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task.** **The name, then the letter count.** ⚠ **Does your number match the speaker\'s?** **That comparison is the whole task** — **two people who agree on eight letters but disagree on the name have found a real error, and neither of them would have found it alone.**'));
out.push(stage('4', 'Your turn – sample notes'));
out.push(sample('Sample — four hard names over a telephone', [
  '**I heard:** _Mouallem_   **Letters:** 8   **✓ correct**',
  '**I heard:** _Tarabishi_   **Letters:** 9   **✓ correct**',
  '**I heard:** _Shamsi_   **Letters:** 6   **✗ it was Shamseddine — 12**',
  '**I heard:** _Nassif_   **Letters:** 6   **✓ correct**',
]));
out.push(note("The third row is the useful one and every class produces one or two: a short name heard inside a long one. Shamsi is a real surname and so is Shamseddine, and the letter count is the only thing that catches it. That is why the count is in the read-back and not just the letters."));
out.push(stage('4R', 'Report – sample'));
out.push(p('**Report (sample):**  _My partner said Shamseddine. I wrote Shamsi. I made it six letters. It was twelve. It was wrong._'));
out.push(p('⚠ **Take TWO counts at the end of this stage:** **how many names were right FIRST TIME, and how many were right AFTER SPELLING.** **The two figures side by side are the argument for _can you spell it, please_** — **and they are usually about four and sixteen.**'));
out.push(p('**Board clinic:** four names said once, fast, then spelled. ⚠ **The class sees the difference rather than being told it.** **Do not say anything between the two rounds.**'));
out.push(stage('5', 'Read'));
out.push(p('**1** Three.  **2** Saeed, Fadi — he knows him.  **3** The caller rang off before Ammar asked for his name.'));
out.push(p('⚠ **Question 1 is a counting question with a trap in it: there are FOUR rows and three names.** **A learner who answers four has counted the calls.** ⚠ **And question 3 is the one with the honesty in it** — **the lost call is written on the list, which is the Writer\'s box.**'));
out.push(stage('6', 'Write with help – sample'));
out.push(sample('Sample answer (23 words)', [
  '**CALLS — TUESDAY 17 MARCH**',
  table(['Time', 'Name _(surname first)_', 'Letters', 'Spelled?'], [
    ['7.40', 'Mouallem, Ghassan', '8', '✓ yes'],
    ['8.55', 'Bitar, Majd', '5', '— no, I know him'],
    ['10.10', 'Shamseddine, Lina', '12', '✓ yes'],
    ['11.30', '_(did not get it)_', '—', '✗ rang off'],
  ], [0.8, 2.2, 0.8, 1.6]),
  '⚠ **4 calls. 3 names. 1 lost. S.Q.**',
]));
out.push(p('**What to credit.** ⚠ **Surname first** — **Unit 1.3 again, and for the same reason: a list is for finding a name in, and you find it by the surname.** ⚠ **And the LOST calls written down.** **A list of three names from four calls is a lie by omission; a list that says one got away is honest, and somebody in the office may know who it was.**'));
out.push(stage('6P', 'Check together – sample'));
out.push(sample('Sample — what a learner actually says', [
  '**(pointing)** Here. **(reading)** "Ghassan Mouallem". ⚠ **Surname first. Mouallem, Ghassan.**',
  '**(pointing)** at the bottom. **(reading)** "3 names". ⚠ **How many calls? Where is the lost one?**',
]));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **Two learners read their LOST line and the class says whether anybody could work out who it was.** **_11.30, a man about the invoice, Homs accent_ gives three handles.** **_Did not get it_ gives none** — **and both are honest, which makes this a question about usefulness rather than truthfulness.**'));
out.push(stage('7', 'Write freely – sample (32 words)'));
out.push(sample('Sample answer', [
  '**A man rang about a big order and I could not get his name. He said it four times. I was too embarrassed to ask for the letters. He never rang back.**',
]));
out.push(p('⚠ **_I was too embarrassed to ask for the letters_ is the sentence this cycle exists to make unnecessary**, **and a learner who has written it down in English has already half-solved it.** **Do not comment on the embarrassment.** **Point at the three sentences that replace it.**'));
out.push(stage('7P', 'Respond – sample'));
out.push(p('**Sample slip:**  _Did he ring back?_ — **_No. He went to the other shop._**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Three papers, then the count: how many lost callers rang back?** **Almost none, and that is the price.** **A caller who gets a man who cannot take his name does not ring twice** — **he rings somebody else, and nobody at your work ever finds out.**'));
out.push(stage('HW', 'Homework – sample'));
out.push(sample('Sample answer (26 words)', [
  '**Q-A-S-S-A-R, 6. M-A-N-S-O-U-R, 7. T-A-R-A-B-I-S-H-I, 9. S-H-A-M-S-E-D-D-I-N-E, 12. A-Y-O-U-B, 5. M-O-U-A-L-L-E-M, 8. Six names, six counts.**',
]));

out.push(pb());
// ===================== 6.3 =====================
out.push(h2('6.3  One moment, please'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **Listen for whether anybody says anything at all.** **In most rooms the honest answer is that the telephone goes down on the counter in silence**, **and the caller hears a shop.**'));
out.push(p('**b**  Open. ⚠ **Do the counting physically, in silence, with the class.** **Ten seconds is a long time in a quiet room and twenty is uncomfortable** — **which is exactly the information the cycle needs and no amount of explanation delivers it.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  A — ten seconds.   **b**  **1** He finds a pen and the slip pad.  **2** _Thank you for waiting._'));
out.push(p('⚠ **The content is in the caller\'s complaint about somebody else:** _Last week somebody left me for four minutes._ **And Ammar\'s answer, which is the line of the cycle:** _Four minutes is not one moment._ **Write it on the board.** **The caller tells him to, and he is right.**'));
out.push(p('⚠ **And the fix, which is not a sentence at all:** _I had no pen._ **Most of _one moment_ is a man looking for a pen.** **That is a thing you solve ONCE — the pen and the pad live next to the telephone — instead of apologising for every day.** ⚠ **It is the first time in this book that the answer to a language problem is furniture.**'));
out.push(stage('3', 'Practise – sample with card 1'));
out.push(dlg(null, [
  ['A', 'One moment, please.'],
  ['B', 'Yes.'],
  ['A', '_(ten seconds, counted out loud)_  Thank you for waiting. Your name again, please.'],
  ['B', 'Mouallem.'],
  ['A', 'Mr Khalil is not here. Can I take a message?'],
]));
out.push(note("Make them really count, out loud, together — and run card 2 as well, which is twenty-five seconds. The pair who have sat through twenty-five counted seconds know why there is a line for twenty seconds on the card, and the pair who have only done ten do not. It costs forty seconds of lesson time and it is the only way to teach it."));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task.** **How long was the wait, and did the speaker say _thank you for waiting_?** ⚠ **The second half is the one that gets dropped** — **a speaker who comes back straight into business has done the hard part and skipped the three words that make it work.**'));
out.push(stage('4', 'Your turn – sample notes'));
out.push(sample('Sample — waiting at my work', [
  '**Why they waited:** I went to ask the manager a price.   **How long:** about a minute.   **Did anybody tell them:** no.',
  '**Why they waited:** I went to the back to count stock.   **How long:** three minutes.   **Did anybody tell them:** I said one moment and then nothing.',
  '**Why they waited:** the line was engaged upstairs.   **How long:** forty seconds.   **Did anybody tell them:** no.',
  '**Why they waited:** I was looking for a pen.   **How long:** twenty seconds.   **Did anybody tell them:** no.',
]));
out.push(note("Column three is almost always no, and that is the finding. The fourth row is the one to circle: twenty seconds of a caller's time spent on a pen, several times a day, in a workplace where a pen costs nothing. Add it up with the class — four calls a day at twenty seconds is an hour a month."));
out.push(stage('4R', 'Report – sample'));
out.push(p('**Report (sample):**  _People wait about a minute for a price. Nobody tells them. I say one moment and then they hear the shop._'));
out.push(p('⚠ **Ask for the longest wait in the room, as a number.** **Somebody will say five minutes and somebody will say _I do not know, I forgot about him_.** **The second answer is the honest version of the first.**'));
out.push(p('**Board clinic:** ⚠ **do this one exactly as written.** **Put the telephone down for thirty seconds in silence and let the class sit in it.** **Then do it again with _I am sorry — one more moment_ at twenty seconds.** **The second version is bearable and the class will say so without being asked.**'));
out.push(stage('5', 'Read'));
out.push(p('**1** _I am sorry — one more moment._  **2** Next to the telephone.  **3** The caller\'s number, to call him back.'));
out.push(p('⚠ **Question 2 is the answer that is not language, and it is the one to mark hardest.** **A card full of apologies with no fix on it is a card for a problem nobody is solving.**'));
out.push(stage('6', 'Write with help – sample'));
out.push(sample('Sample answer (30 words)', [
  '**WAITING — THE COUNTER TELEPHONE**',
  '**0 seconds** — _One moment, please._ ⚠ **Before you put it down. Always.**',
  '**10 seconds** — _Thank you for waiting._',
  '**20 seconds** — _I am sorry — one more moment._',
  '**60 seconds** — _Can I take your number and ring you back?_',
  '⚠ **The fix:** the price list lives UNDER the till, not in the office. Nobody walks anywhere.',
]));
out.push(p('**What to credit.** ⚠ **TIMES down the left, not steps.** **A time tells the reader when to say the line; _then say sorry_ does not.** **At twenty seconds a man with _20 seconds_ on his card looks at his watch; a man with _after a while_ says nothing and loses the call.** ⚠ **And a FIX, not only apologies.**'));
out.push(stage('6P', 'Check together – sample'));
out.push(sample('Sample — what a learner actually says', [
  '**(pointing)** Here. **(reading)** "Then apologise". ⚠ **When? How many seconds?**',
  '**(pointing)** at the bottom. **(reading)** nothing. ⚠ **What would stop the waiting? Write the fix.**',
]));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **Two learners read their FIX and the class says whether it would stop the waiting.** **_I will be quicker_ is not a fix.** **_The price list lives under the till_ is.** **The test is whether it changes where something IS, or who knows something, rather than how hard somebody tries.**'));
out.push(stage('7', 'Write freely – sample (33 words)'));
out.push(sample('Sample answer', [
  '**Callers wait two or three minutes at our shop because the prices are in the office upstairs. Two have rung off this month. If the list was by the till nobody would wait.**',
]));
out.push(p('⚠ **The best answers to this stage are not about English at all and should be marked as the best anyway.** **A learner who has diagnosed a lost-call problem and proposed moving a piece of paper has used the unit for its real purpose.**'));
out.push(stage('7P', 'Respond – sample'));
out.push(p('**Sample slip:**  _Has anybody ever rung off?_ — **_Two this month. One was a hotel order._**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Three papers, then the count: how many callers have rung off waiting?** **And the follow-up that lands: what was the biggest one worth?** **A hotel order lost to a walk upstairs is the cheapest expensive mistake in this book.**'));
out.push(stage('HW', 'Homework – sample'));
out.push(sample('Sample answer (22 words)', [
  '**From tomorrow: a pen and a slip pad in a cup beside the telephone, and the price list under the till. Nothing upstairs.**',
]));

out.push(pb());
// ===================== 6.4 =====================
out.push(h2('6.4  He is not here'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **Accept any preposition.** **The content here is WHERE PEOPLE ARE, not the grammar of it** — **and a class that has to produce four locations will find out how little it actually knows about where its colleagues are.**'));
out.push(p('**b**  **The second line helps.** ⚠ **Ask what the caller DOES with each one.** **With the first, he rings again at random. With the second, he rings at two.** **Same test as 3.6 and 5.1** — **what can the other person do with this?**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  C — in Homs until Thursday.   **b**  **1** Where the person is, and when they are back.  **2** He does not say _in a meeting_.'));
out.push(p('⚠ **The last three lines are the sharpest thing in Unit 6:** _You did not say she was in a meeting. — She is at lunch. Why would I say a meeting? — Everybody says a meeting. Nobody is ever at lunch._ ⚠ **Ask the class whether that is true where they work.** **It is, and they will laugh, and then the point lands:** **a caller told _at lunch_ believes _in a meeting_ the next time.**'));
out.push(p('⚠ **And the small one worth marking:** _Or I take a message and she has it at two._ **Ammar offers a better option than the one the caller chose.** **That is 6.6 arriving early and it is also the first time in the book that a storeman improves on a customer\'s plan.**'));
out.push(stage('3', 'Practise – sample with card 1'));
out.push(dlg(null, [
  ['A', 'Is Mr Khalil there?'],
  ['B', 'He is not here. He is in Homs until Thursday.'],
  ['A', 'Thursday. And Mrs Mansour?'],
  ['B', 'She is here. She is at lunch. She is back at two.'],
  ['A', 'Two. I ring back at two.'],
  ['B', 'Or I take a message and she has it at two.'],
]));
out.push(note("Every answer in this drill is two sentences and the second one carries the information. Drill it as a pair, not as a sentence: he is not here / he is in Homs until Thursday, said together, forty times. A learner who can produce the first half without the second has learned the useless half."));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task.** **Two times.** ⚠ **Both of them, and if a pair only gave one, the class should say which person they still cannot reach.**'));
out.push(stage('4', 'Your turn – sample notes'));
out.push(sample('Sample — four people at my work', [
  '**Name:** Khalil, Abu Yasser   **Where:** Homs   **Back:** Thursday morning',
  '**Name:** Mansour, Nour   **Where:** the office, upstairs   **Back:** all day',
  '**Name:** Saeed, Fadi   **Where:** on the road   **Back:** 5.00 today',
  '**Name:** Bitar, Majd   **Where:** the counter   **Back:** all day, but at lunch 1–2',
]));
out.push(note("The fourth row is the most useful shape and it is worth showing the class: here all day AND away for an hour. A caller who is told all day and rings at half past one gets nobody, and feels lied to over a lunch break. The exception in the Back column costs four words."));
out.push(stage('4R', 'Report – sample'));
out.push(p('**Report (sample):**  _Fadi is not here. He is on the road. He is back at five today._'));
out.push(p('⚠ **Count the reports that gave a TIME.** **A time is what makes the sentence useful and _later_ is the same as nothing.** **The figure is usually about half, and the half without a time is the half that is still using _he is not here_ with extra words on it.**'));
out.push(p('**Board clinic:** four answers with no second sentence. ⚠ **The class adds one to each, inventing the information.** **Inventing is fine here** — **the shape is what is being practised.**'));
out.push(stage('5', 'Read'));
out.push(p('**1** Thursday morning.  **2** Majd Bitar — at the counter, all day.  **3** Because a caller is told _back at two_ from a board written yesterday, rings at two, and is told the same thing again.'));
out.push(p('⚠ **Question 3 is the hardest reading question in the unit because the answer is not on the page as a sentence** — **the learner has to work out what goes wrong.** **Accept any answer that gets to _the caller is told something that was true yesterday_.**'));
out.push(stage('6', 'Write with help – sample'));
out.push(sample('Sample answer (26 words)', [
  table(['Name _(surname first)_', 'Where', 'Back'], [
    ['Ayoub, Khaled', 'the bank', '11.00'],
    ['Sayegh, Nadia', 'upstairs', 'all day'],
    ['Nassif, Bassel', 'the market', '2.30'],
    ['Mourad, Hala', 'the counter', 'all day, lunch 1–2'],
  ], [1.8, 2, 1.6]),
  '**Written at:** Tuesday 17 March, 9.15',
  '⚠ **Rub out and rewrite at every change. A board that is wrong is worse than no board.**',
]));
out.push(p('**What to credit.** ⚠ **A TIME at the top** — **without it nobody knows whether _at lunch_ was written an hour ago or yesterday.** ⚠ **_Back_ must be a time or a day, never _soon_ or _later_.** **Surname first.** **And a rule at the bottom about keeping it right.**'));
out.push(stage('6P', 'Check together – sample'));
out.push(sample('Sample — what a learner actually says', [
  '**(pointing)** Here. **(reading)** "Back: soon". ⚠ **Soon is nothing. What time?**',
  '**(pointing)** at the top. **(reading)** "WHO IS WHERE". ⚠ **Written when? A caller needs to know.**',
]));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **Two learners read their _back_ column and the class says whether a caller could use it.** **The test is one question: could I decide when to ring?** **_All day_ passes. _Soon_ does not. _All day, lunch 1–2_ is the best of the three and it costs four words.**'));
out.push(stage('7', 'Write freely – sample (31 words)'));
out.push(sample('Sample answer', [
  '**The manager is the hardest to find. He is at the market, or at the bank, or upstairs. I tell callers he is not here and they ring four times.**',
]));
out.push(p('⚠ **_They ring four times_ is the cost and most learners will produce something like it.** **Four calls instead of one, because the first one was answered with a sentence containing no information.**'));
out.push(stage('7P', 'Respond – sample'));
out.push(p('**Sample slip:**  _Do you ever say "in a meeting"?_ — **_Yes. He is never in a meeting. We have no meetings._**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Three papers, then the count: how many people say _in a meeting_ when it is not true?** **Expect nearly everybody and expect laughter.** ⚠ **Then say the serious half once and stop:** **a caller who is told the truth about a lunch break believes you about a meeting.** **That is the whole argument and it does not need repeating.**'));
out.push(stage('HW', 'Homework – sample'));
out.push(sample('Sample answer (28 words)', [
  '**Tomorrow: Khaled at the bank until 11. Nadia upstairs all day. Bassel at the market, back 2.30. Hala at the counter all day, lunch one to two.**',
]));

out.push(pb());
// ===================== 6.5 =====================
out.push(h2('6.5  Zero nine four four — one one two'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **Listen for whether they group it.** **Most learners say their own number as one long string because they have said it a thousand times**, **and the partner writing it down will get it wrong.** **That failure is the set-up for the box.**'));
out.push(p('**b**  Open. **_zero · nought · oh_ — all three are used and the class must hear all three.** ⚠ **In Syria _zero_ and _sifr_ dominate; British callers say _oh_ and it does not sound like a number at all.** **Say _oh seven_ aloud and watch the room.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  A — 0944 112 233.   **b**  **1** Three times — once by the caller, once again, and once read back.  **2** He asks whether it is _two three three_ or _two two three_.'));
out.push(p('⚠ **The last line is the sentence of the cycle and it came from Abu Yasser:** _a number nobody read back is a number nobody has._ **Put it on the board.** **The read-back is the job, not the polite ending** — **and the caller\'s line before it tells you how rare it is:** _you are the first man here who read it back._'));
out.push(p('⚠ **And _double three_, which is a real listening problem.** **A man who hears _double three_ and writes one three has lost the number**, **and he will not know he has lost it until he rings and gets a stranger.**'));
out.push(stage('3', 'Practise – sample with card 1'));
out.push(dlg(null, [
  ['A', 'My number is 0944 112 233.'],
  ['B', 'One moment, please. Again, please.'],
  ['A', 'Zero nine four four … one one two … two three three.'],
  ['B', 'Zero nine four four … one one two … two three three.'],
  ['A', 'That is it.'],
  ['B', 'The last part. Two three three, or two two three?'],
]));
out.push(note("The last line looks redundant after the caller has said that is it, and it is not: the read-back confirmed the groups but not the digits inside the last one, and two three three against two two three is exactly the pair a telephone destroys. Keep it. The pairs who find it fussy are the pairs who have not yet rung a wrong number twice."));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task.** **Write the number, then check it against the speaker\'s paper digit by digit.** ⚠ **Digit by digit, against the paper** — **not by reading the two out loud, which is how two wrong numbers agree with each other.**'));
out.push(stage('4', 'Your turn – sample notes'));
out.push(sample('Sample — four numbers over a telephone', [
  '**I wrote:** 0944 112 233   **Read back:** ✓   **✓ correct**',
  '**I wrote:** 011 557 788   **Read back:** ✓   **✓ correct**',
  '**I wrote:** 0932 445 661   **Read back:** ✗   **✗ it was 0932 445 616**',
  '**I wrote:** 0988 300 410   **Read back:** ✓   **✓ correct**',
]));
out.push(note("The third row is the finding and it is the one to show the class: the only number that was wrong is the only one that was not read back. One row, two columns, and the argument for the whole cycle. If no row in the room comes out that way, run the stage again with the read-back forbidden on two of the four."));
out.push(stage('4R', 'Report – sample'));
out.push(p('**Report (sample):**  _I wrote 0932 445 661. I did not read it back. It was wrong in the last group — 616, not 661._'));
out.push(p('⚠ **Two counts again, side by side:** **how many numbers were right, and how many were right WITHOUT a read-back.** **The second figure is always the lower one** — **and the pair of numbers does the teaching.**'));
out.push(p('**Board clinic:** a number said once, fast, with no groups; then the same number in groups. ⚠ **Compare what the class wrote.** **It is the same clinic as 6.2 and the class should notice that** — **grouping and spelling are one skill wearing two hats.**'));
out.push(stage('5', 'Read'));
out.push(p('**1** Three.  **2** Two digits are missing — _0988 3?? 410_.  **3** Because nine digits out of eleven is not nothing, and somebody in the office may recognise it.'));
out.push(p('⚠ **Question 3 is the hardest idea in the cycle and it is the same idea as the lost name in 6.2:** **a partial record beats a blank line.** **A blank is the only version of that number that is certainly useless** — **and the question marks tell the next reader exactly where the hole is.**'));
out.push(stage('6', 'Write with help – sample'));
out.push(sample('Sample answer (25 words)', [
  '**NUMBERS TAKEN — TUESDAY 17 MARCH**',
  table(['Time', 'Name', 'Number _(in groups)_', 'Read back?'], [
    ['7.40', 'Mouallem', '0944 112 233', '✓ yes'],
    ['8.55', 'Bitar', '011 557 788', '✓ yes'],
    ['10.10', 'Shamseddine', '0932 445 616', '✓ yes'],
    ['11.30', '_(no name)_', '0988 3?? 410', '✗ rang off'],
  ], [0.8, 1.6, 1.8, 1.4]),
  '⚠ **3 good. 1 not read back. S.Q.**',
]));
out.push(p('**What to credit.** ⚠ **The numbers written in GROUPS on the page.** **A twelve-digit string with no gaps is a number you will misread next week, and you are next week\'s reader.** ⚠ **A read-back column, ticked or crossed.** ⚠ **And bad numbers written with question marks rather than left out.**'));
out.push(stage('6P', 'Check together – sample'));
out.push(sample('Sample — what a learner actually says', [
  '**(pointing)** Here. **(reading)** "0944112233". ⚠ **No gaps. Put the groups in.**',
  '**(pointing)** at this row. **(reading)** nothing in the last column. ⚠ **Did you read it back? Tick or cross.**',
]));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **Two learners read one number to the class, IN GROUPS, and the class writes it and checks.** **Twenty people writing one number at once produces two or three wrong versions**, **and the speaker finds out which group was unclear.** **That is better feedback than any mark.**'));
out.push(stage('7', 'Write freely – sample (32 words)'));
out.push(sample('Sample answer', [
  '**A customer gave me his number and I wrote 616 instead of 661. I rang a stranger twice. He waited two days for us and then bought the doors somewhere else.**',
]));
out.push(p('⚠ **The three-part shape — the digits, the wrong calls, the lost business — is what to look for.** **Learners stop after the first part because the digit error feels like the mistake.** **The mistake was two transposed digits; the LOSS was two days and a customer.**'));
out.push(stage('7P', 'Respond – sample'));
out.push(p('**Sample slip:**  _Did you ever get hold of him?_ — **_No. He came in a week later and told us._**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Three papers, then the count: how many lost calls were never got back?** **Most.** **A wrong number is a silent failure** — **nobody rings to tell you that you wrote their number down wrong, which is why the read-back has to be a habit and not a judgement.**'));
out.push(stage('HW', 'Homework – sample'));
out.push(sample('Sample answer (27 words)', [
  '**0944 112 233 · 011 557 788 · 0932 445 616 · 0988 300 410 · 0955 201 377 · 011 231 4455. All in groups. All read aloud twice.**',
]));

out.push(pb());
// ===================== 6.6 =====================
out.push(h2('6.6  I will tell him'));
out.push(stage('1', 'Get ready'));
out.push(p('**a**  Open. ⚠ **Expect _OK_ or _tayyeb_ or a nod.** **A nod is the commonest answer and it is also the least reliable promise there is** — **and on a telephone nobody can see it, which the class should notice for itself.**'));
out.push(p('**b**  **The second line.** ⚠ **Ask what makes it believable.** **The TIME.** **_I will tell him_ is a hope; _I will tell him at two_ is something the caller can check** — **and a promise somebody can check is a promise that gets kept.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  A — at two.   **b**  **1** On her desk.  **2** Tell her at two as well — he does both.'));
out.push(p('⚠ **The whole cycle is in two lines:** _Both. The slip is if I forget. I am new and I might forget._ ⚠ **A man who plans for his own forgetting is not careless — he is awake**, **and that is worth saying to a class that has been taught that admitting a weakness is a confession.**'));
out.push(p('⚠ **And the cost line:** _A day late lost us a lorry._ **Not _a day late is bad_.** **A lorry.** **Every rule in this book has a price attached to it somewhere, and the prices are what make the rules survive the lesson.**'));
out.push(stage('3', 'Practise – sample with card 1'));
out.push(dlg(null, [
  ['A', 'So she has it at two?'],
  ['B', 'I will tell her at two. And the slip goes on her desk now.'],
  ['A', 'Both?'],
  ['B', 'Both. The slip is if I forget.'],
  ['A', 'You will not forget.'],
  ['B', 'Last Tuesday I forgot one. So now I do both.'],
]));
out.push(note("I will tell her at two is a chunk and should be drilled as one word. At A1 nobody needs to know why it is will, and a teacher who explains the future here has spent ten minutes buying nothing — the learner needs the phrase automatic with a time on the end, and the grammar arrives two levels up."));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task.** **TWO things.** ⚠ **Two, not one.** **A pair who promised only the telling, or only the slip, have performed half the cycle** — **and the listeners naming which half is missing is better than the teacher doing it.**'));
out.push(stage('4', 'Your turn – sample notes'));
out.push(sample('Sample — four messages I have taken', [
  '**The message:** a price for the hotel   **What I said:** _I will tell him._   **What I did:** told him   **Did it arrive:** yes',
  '**The message:** a lorry coming early   **What I said:** _OK._   **What I did:** nothing   **Did it arrive:** no — the lorry waited an hour',
  '**The message:** an invoice question   **What I said:** _I will tell her at two._   **What I did:** slip on her desk and told her   **Did it arrive:** yes',
  '**The message:** a man asking for Fadi   **What I said:** _I will tell him._   **What I did:** forgot   **Did it arrive:** no',
]));
out.push(note("Rows two and four are the useful ones and most learners have both: the message answered with OK and the message promised properly and then forgotten. Put the two side by side. The first failed at the promise and the second failed at the memory, and only one of those two can be fixed by a sentence — which is why the slip exists."));
out.push(stage('4R', 'Report – sample'));
out.push(p('**Report (sample):**  _I said I would tell Nour at two. I wrote a slip and put it on her desk. She got it at two._'));
out.push(p('⚠ **Count the reports that promised BOTH.** **Both is the answer and the figure will start low** — **because doing two things for one message looks like distrust of yourself, and the cycle\'s argument is that it is not.**'));
out.push(p('**Board clinic:** four promises, two with no time. ⚠ **The class adds a time to each.** **Then read the four aloud in their improved form** — **hearing the good version is half the clinic.**'));
out.push(stage('5', 'Read'));
out.push(p('**1** For Nour Mansour, taken by Ammar Zreik.  **2** That the number was read back.  **3** He put the slip on her desk AND told her at two.'));
out.push(p('⚠ **Question 2 is about the smallest mark on the slip and the most useful.** **A number with no tick is a number the reader should ring once and not trust** — **and that single tick carries the whole of 6.5 into the written record.**'));
out.push(stage('6', 'Write with help – sample'));
out.push(sample('Sample answer (34 words)', [
  '**MESSAGE**',
  '**For:** Nadia Sayegh   **Taken by:** Samih Qassar',
  '**Date:** 17 March   **Time:** 10.15',
  '**From:** Lina Shamseddine _(S-H-A-M-S-E-D-D-I-N-E)_',
  '**Number:** 0932 445 616  ⚠ **read back ✓**',
  '**Message:** The Thursday order is 6 pallets, not 4. She has changed it with the mill.',
  '⚠ **She rings back at three. I told Nadia at 10.20 as well. S.Q.**',
]));
out.push(p('**What to credit.** ⚠ **_Taken by_ matters as much as _for_** — **a message with no taker is a message nobody can ask a question about, and there is always a question.** ⚠ **The caller\'s name spelled out.** ⚠ **The read-back tick.** ⚠ **And a last line saying what happens NEXT** — **the slip is the record of a job that is still going on, not the end of one.**'));
out.push(stage('6P', 'Check together – sample'));
out.push(sample('Sample — what a learner actually says', [
  '**(pointing)** at the top. **(reading)** "For: Nadia". ⚠ **Taken by who? If she asks, who does she ask?**',
  '**(pointing)** at the number. **(reading)** "0932 445 616". ⚠ **Did you read it back? No tick.**',
]));
out.push(stage('6R', 'Share'));
out.push(p('⚠ **Two learners read their slip and the class answers one question: could you act on this WITHOUT asking anybody anything?** **That is the test of a message slip and it is a hard one.** **A slip that needs one question has cost somebody a walk, and a slip that needs two has not been written yet.**'));
out.push(stage('7', 'Write freely – sample (34 words)'));
out.push(sample('Sample answer', [
  '**A man rang about a lorry coming early and I said OK and forgot. The lorry came at six and waited an hour. The driver found me and told me himself.**',
]));
out.push(p('⚠ **_The driver found me and told me himself_ is the shape of nearly every answer to this stage:** **the message arrives eventually, through the person who was waiting for it.** **That is the most expensive way for information to travel and it is the normal way.**'));
out.push(stage('7P', 'Respond – sample'));
out.push(p('**Sample slip:**  _Who found out it was lost?_ — **_The driver. He waited an hour in the yard._**'));
out.push(stage('7R', 'Share'));
out.push(p('⚠ **Three papers, then the count: how many lost messages were found by the person who was WAITING for them?** **Nearly all of them.** **Say the number and then the sentence it implies:** **a lost message is not found by the system, it is found by the person it was costing** — **which is the whole of 6.7 in one line.**'));
out.push(stage('HW', 'Homework – sample'));
out.push(sample('Sample answer (23 words)', [
  '**MESSAGE. For: ___ Taken by: ___ Date: ___ Time: ___ From: ___ (spelled) Number: ___ read back ___ Message: ___ What happens next: ___**',
]));

out.push(pb());
// ===================== 6.7 =====================
out.push(h2('6.7  Review: the message slip'));
out.push(stage('1', 'Get ready – Unit 6 quiz'));
out.push(table(['', 'The answer'], [
  ['**6.1**', '_[Company], good morning._ ⚠ **Slowly, with a gap, then stop.**'],
  ['**6.2**', '_Your name, please._ → _Can you spell it, please?_ → **the letters, the count, the name.**'],
  ['**6.3**', '_One moment, please._ → _Thank you for waiting._'],
  ['**6.4**', '_She is at lunch. She is back at two._ ⚠ **Both sentences.**'],
  ['**6.5**', '_Zero nine four four … one one two … two three three._ ⚠ **In groups.**'],
  ['**6.6**', '_I will tell her at two._ ⚠ **With a time.**'],
], [1, 6]));
out.push(p('⚠ **Tick, do not mark.** **6.4 is the one to listen hardest to** — **a learner who gives only the first sentence has given the useless half, and should hear the pair once before being ticked.**'));
out.push(stage('2', 'Listen and read'));
out.push(p('**a**  B — it was taken perfectly and never passed on.   **b**  **1** The name spelled, the number read back, the invoice problem, and the time he rings.  **2** Under the slip pad, on Nour\'s desk.'));
out.push(p('⚠ **This is the cruellest mediation in Book 1 and it should be played straight.** **The slip was perfect. Ammar put it on the desk AND told her at two. Nour was on the other telephone and put her own pad on top of it.** **Nobody did anything wrong and the invoice is paid for four boxes that never arrived.**'));
out.push(p('⚠ **Abu Yasser\'s line is the summary and it is worth reading aloud twice:** _So the slip was perfect, the man did both, and the message is three days late._ **If the class wants somebody to blame, let them look.** **They will not find one, and that is the lesson Book 1 ends on.**'));
out.push(stage('3', 'Practise'));
out.push(p('**The two sides, and both are true.** ⚠ **Do not let a learner play Nour as careless.** **She came back from lunch, put her pad down, and was on another call when he spoke to her** — **three ordinary things.** ⚠ **And Ammar did one thing more than 6.6 asks for.** **There is nothing left either of them could have done.**'));
out.push(stage('3R', 'Perform'));
out.push(p('**Listener task.** ⚠ **_Nobody\'s._** **If the class insists on blaming somebody, ask what that person should have done differently** — **and keep asking until the answer becomes a change to the system rather than to a person.** **That conversion is the whole of the cycle.**'));
out.push(stage('4', 'Your turn – sample'));
out.push(sample('Sample — lost between two people who both did their job', [
  '**What was passed:** a holiday form.   **What each person did:** I filled it in and put it in his tray; he emptied the tray into a folder.   **Where it stopped:** in the folder, behind the other papers, for five weeks.',
  '**What was passed:** a price change from the mill.   **What each person did:** the driver told the storeman; the storeman told the counter.   **Where it stopped:** at the counter — the man who was told left at two and the evening man never heard.',
]));
out.push(note("The second sample is the commoner shape and it is worth naming: the message travelled correctly through three people and died at a shift change. Nothing in it was anybody's fault and the gap is a handover, which is Unit 12 — the note you leave for the man who comes after you. Point forward to it; Book 1 ends by naming the thing Book 2 is for."));
out.push(stage('4R', 'Mediate and report'));
out.push(p('**The three positions, in full.**'));
out.push(table(['', 'Right about', 'Gives up'], [
  ['**Ammar**', '⚠ **he did everything 6.6 asks for and one thing more — a perfect slip AND the telling, at the time he promised**', '**nothing he did.** ⚠ **Only where he PUTS it: flat on a desk becomes standing on a spike.**'],
  ['**Nour**', '⚠ **she was on another call and never heard him — and a slip lying flat on a desk is invisible the moment anything is put down on it**', '**the desk.** ⚠ **Slips do not live on her desk any more; they live on the spike by the telephone.**'],
  ['**The fix**', '⚠ **a flat slip is a lost slip** — **one place, standing up, by the telephone; and the second telling WAITS until the person is off the other line**', '**nothing.** ⚠ **It costs a spike and ten seconds of patience.**'],
], [1.2, 4.4, 3.6]));
out.push(p('**Report (sample):**  _Ammar is right because he did both things at the time he promised. Nour is right because she was on another call and a flat slip disappears under the next thing put down. So the slips go on a spike by the telephone, standing up, and the second telling waits until the person is free._'));
out.push(p('⚠ **The words to keep:** _the slip was perfect, the man did both, and the message is three days late._'));
out.push(p('⚠ **And then the five, laid side by side, which is how Book 1 ends.** **Abu Raed\'s gate book in 1.7 — nine perfect years in a script the office cannot read. Hani\'s eleven swaps in 3.7 — the right man asked every time, never written down. The roll behind the door in 4.3, and Fouad\'s eleven good decisions in 4.7 — every one of them better than the map. The driver and the four minutes in 5.7 — both men right, both men paying. And now a perfect slip under a pad.** ⚠ **Every one was somebody doing their job well into a system with one gap in it.** **Say that to the class in Arabic once, and then say what Book 2 is:** **Book 2 is about the gaps.**'));
out.push(stage('5', 'Read – exam practice'));
out.push(table(['Q', '1', '2', '3', '4', '5'], [['Answer', 'B', 'B', 'A', 'B', 'C']], [1.2, 0.8, 0.8, 0.8, 0.8, 0.8]));
out.push(p('⚠ **Question 3 is the hardest of the five** — **_ring once, do not trust it_ has to be read as _it may be wrong_, which is an inference rather than a paraphrase.** **A learner who chose B has read _do not_ and stopped.**'));
out.push(p('⚠ **Tell the class what this task is, for the sixth and last time in Book 1.** **A2 Key Reading Part 1, which they sit at the end of the NEXT course** — **same five notices, same three choices, one step up.** **They have now done it six times.** **Say that: it is the first exam task in their lives that has stopped being frightening.**'));
out.push(stage('6', 'Write with help – sample'));
out.push(sample('Sample answer (30 words, four sentences)', [
  '**For:** Abu Yasser',
  '**Mouallem rang at 1.35. He says the March invoice is wrong — 16 boxes, we paid for 12. He wants a credit note. He rings back at four.**',
]));
out.push(table(['Marks', 'For'], [
  ['**1**', '**who called — a name**'],
  ['**1**', '**a time for the call**'],
  ['**1**', '**what it is about**'],
  ['**1**', '⚠ **what he WANTS — not just the problem**'],
  ['**1**', '⚠ **what happens next, with a time**'],
], [1, 5]));
out.push(stage('6P', 'Check together'));
out.push(p('⚠ **Count the sentences out loud, with fingers.** **Four.** **Sixth unit running, and by now most of the class does it unprompted.** ⚠ **If they do, say so and say why:** **they have counted sentences six times and the counting has become automatic, which is what the whole of Lesson B has been for.**'));
out.push(stage('7', 'Write freely – exam practice'));
out.push(p('⚠ **Four sentences, about thirty words, and the last one must be the thing the reader must DO, with a TIME in it.** **A message that reports a call and does not say when anything happens next is a message that has to be chased** — **and chasing is what cost four boxes in this cycle.**'));
out.push(sample('Sample answer (29 words, four sentences)', [
  '**Shamseddine rang at 10.15. She says the Thursday order is six pallets, not four. She has changed it with the mill already. She rings back at three.**',
]));
out.push(stage('✓', 'Marking the unit check'));
out.push(table(['**Q**', '1', '2', '3', '4', '5', '6', '7', '8'], [['Answer', 'b', 'c', 'a', 'b', 'a', 'c', 'b', 'a']], [1.2, 0.6, 0.6, 0.6, 0.6, 0.6, 0.6, 0.6, 0.6]));
out.push(box('Marking the unit check', [
  '**A  Words — 8 marks**, one each. ⚠ **Question 4 is the only piece of grammar in the unit:** _thank you for **waiting**_, **not _wait_ or _waited_.** **It is a chunk and it should have been learned as one** — **a learner who gets it wrong has learned the idea and not the words, which is the one thing 6.1 said not to do.** ⚠ **Question 6 — _double three is TWO threes_ — is a listening fact wearing a vocabulary question\'s clothes, and it is the one that costs a telephone number.**',
  '**B  Listening — 6 marks**, one each. **Qassar (1) · six (1) · 0932 445 661 (1) · yes (1) · Mrs Mansour (1) · four o\'clock (1).** ⚠ **Item 3 must be in groups to score** — **a learner who writes 0932445661 has the digits and has not done the task, and the task is the thing that stops the digits being wrong.** ⚠ **Item 5 is in Ammar\'s THIRD line, before the name is even asked for**, **and learners listening for the message will have stopped attending by then.**',
  '**C  Reading — 3 marks:** **Ammar Zreik (1) · that the number was read back (1) · put the slip on her desk AND told her at two (1).** ⚠ **The third mark needs BOTH.** **Sixth unit running on the both-halves rule, and by Unit 6 the class should expect it.**',
  '**D  Writing — 8 marks:** **four sentences (2) · the caller named (1) · a time for the call (1) · what it is about (1) · what he wants (1) · what happens next with a time (2).** ⚠ **The last one is worth two** — **it is the thing that separates a message from a note, and it is what the whole unit has been for.**',
  '**Total 25.** ⚠ **The profile to expect: A split on questions 4 and 6, B split on item 3, C split on the third mark, D the best in the book.** ⚠ **This is the last unit check of Book 1, so say the shape of the six out loud when you hand it back:** **A has been flat, B has risen, C has risen slowly, and D has risen every single time.** **D is the one that matters and it has gone up six times.**',
], C.lteal, C.navy));
out.push(note("Teacher's note. Six things, and this is the last unit of the book so the sixth is about the book. First, the fear. The telephone is the hardest English there is and the room knows it: no face, no paper, no pointing, and the caller does not know you are learning. Say that before you begin. Pretending the difficulty is not real costs you the quiet learners for the whole unit. Second, the six sentences. Do not enrich them, do not offer alternatives, do not teach a synonym. A man with six fixed sentences can answer any telephone in Syria and a man with a hundred words and no sentences cannot answer one; the fixedness is the method, and a teacher who improves on it has removed the only thing a frightened learner can hold. Third, back to back. Every speaking stage, with no exceptions and no negotiation. A pair who can see each other's faces are not practising a telephone call, and the whole difficulty of the unit lives in not being able to see. Fourth, the answers that are not language. The pen lives next to the telephone. The price list lives under the till. The slips go on a spike. Three times in this unit the solution is furniture rather than English, and that is not a digression — it is the first time in the course that a learner is asked to change the place they work rather than the way they speak, and it will come back in every unit of Book 2. Fifth, the numbers on the board. How many company names were inaudible; how many names were right before and after spelling; how many numbers were right with and without a read-back; how many callers rang off; how many lost messages were found by the person waiting for them. Each pair of figures is an argument that makes itself and none of them needs a comment from you. Sixth, the ending. Five times in six units something has gone wrong with nobody at fault: Abu Raed's gate book, Hani's eleven swaps, the roll behind the door and Fouad's shelf map, the driver's four minutes, and a perfect slip under a pad. Lay all five in front of the class — in Arabic, if that is what it takes — and say the sentence they share: every one was somebody doing their job well into a system with one gap in it. Then say what comes next. Book 2 is about the gaps."));

if (require.main === module) L.build(out, process.argv[2], 'Proactive Business English A1 · Book 1 · Syria Edition · Unit 6 · Answer Key');
module.exports = out;
